(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.013-t*0.18)*15 + Math.sin((x+y)*0.008+t*0.15)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.2)*14 + Math.cos((x-y)*0.009-t*0.12)*10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025+t*0.4)*8 + Math.cos(sy*0.02-t*0.35)*6;
  const w2y = Math.cos(sy*0.023-t*0.38)*7 + Math.sin(sx*0.019+t*0.42)*5;
  const wx = sx + w2x, wy = sy + w2y;
  const dist = Math.sqrt((wx-cx)**2 + (wy-cy)**2);
  const ang = Math.atan2(wy-cy, wx-cx);
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.5],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.75],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.14, 1.3, 0.85],
    [400+Math.cos(t*0.55+1)*80, 220+Math.sin(t*0.75)*60, 0.11, 2.1, 0.65],
    [200+Math.sin(t*0.7+4)*90, 200+Math.cos(t*0.3+3)*70, 0.13, 1.8, 0.7],
    [300+Math.cos(t*0.25+5)*110, 100+Math.sin(t*0.45+1)*80, 0.09, 2.4, 0.55]
  ];
  let aS = 0, iS = 0, crossI = 0;
  for (let si = 0; si < src.length; si++) {
    const [sX, sY, f, sp, amp] = src[si];
    const d = Math.sqrt((wx-sX)**2 + (wy-sY)**2);
    aS += Math.sin(d*f - t*sp) * amp;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * amp;
    if (si < src.length - 1) {
      const [nX, nY, nf, nsp] = src[si + 1];
      const d2 = Math.sqrt((sX-nX)**2 + (sY-nY)**2);
      crossI += Math.sin((d+d2)*f*0.5 - t*sp*0.8) * 0.3;
    }
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, cross = crossI/(n-1);
  const bg1 = (Math.sin(wx*0.04+wy*0.025+t*0.8) + Math.sin(wx*0.03-wy*0.04+t*1.1))/2;
  const bg2 = Math.sin((wx+wy)*0.12+t*2.5)*0.2 + Math.sin((wx-wy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(wx*0.08+t*0.6)*Math.sin(wy*0.06-t*0.4)*0.15;
  const bg = bg1 + bg2 + bg3;
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.3;
  const sp2 = Math.sin(dist*0.08+ang*2-t*2.0)*Math.cos(dist*0.06-ang*5+t*1.8)*0.2;
  const spiral = sp1 + sp2;
  const fine = Math.sin(wx*0.3+t*3)*Math.sin(wy*0.25-t*2.5)*0.1;
  const cell = Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15) + Math.sin((wx+wy)*0.1+t)*0.5)*1.5)*0.25;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + cross*0.4 + fine)*2.0);
  const edge = Math.abs(reaction);
  const blend = reaction*0.6 + cell*0.2 + Math.tanh(cross)*0.2;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[10,35,82],[15,72,115],[18,110,125],[25,155,115],
    [80,175,80],[160,188,55],[225,195,48],[235,148,52],[215,92,58],
    [185,55,62],[125,30,58],[72,18,52],[30,12,48],[5,10,45]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx - i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.15 + edge*0.1;
  const glow = Math.max(0, reaction)*0.3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum + glow*65)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum + glow*45)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum + glow*20)|0)
  ];
}
